use crunch_rust_cache_core::{canonical_rust_action, RustUnitActionInput};
use crunch_rust_cache_core::wrapper::{
    arguments_identity_blake3, environment_identity_blake3, seal_wrapper_manifest,
    seal_wrapper_request, DeclaredInputKind, WrapperInvocationManifestInput, WrapperRequestInput,
};
use serde_json::Value;
use std::path::Path;
use std::io::Write;

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args[1] == "hash" {
        let kind = match args[2].as_str() {
            "file" => DeclaredInputKind::File,
            "directory" => DeclaredInputKind::Directory,
            _ => panic!("invalid declared kind"),
        };
        println!("{}", crunch_rustc_wrapper::declared_input_digest_blake3(
            Path::new(&args[3]), kind, 8_589_934_592).unwrap());
        return;
    }
    if args[1] == "request" {
        let request: Value = serde_json::from_slice(&std::fs::read(&args[3]).unwrap()).unwrap();
        let mut stream = std::os::unix::net::UnixStream::connect(&args[2]).unwrap();
        stream.set_read_timeout(Some(std::time::Duration::from_secs(120))).unwrap();
        stream.set_write_timeout(Some(std::time::Duration::from_secs(120))).unwrap();
        crunch_rustc_wrapper::write_frame(&mut stream, &request, 8_388_608).unwrap();
        stream.flush().unwrap();
        let response: Value = crunch_rustc_wrapper::read_frame(&mut stream, 8_388_608).unwrap();
        println!("{}", serde_json::to_string(&response).unwrap());
        return;
    }
    assert_eq!(args[1], "prepare");
    let mut value: Value = serde_json::from_slice(&std::fs::read(&args[2]).unwrap()).unwrap();
    let action = canonical_rust_action(serde_json::from_value::<RustUnitActionInput>(value["action"].take()).unwrap()).unwrap();
    let mut request: WrapperRequestInput = serde_json::from_value(value["request"].take()).unwrap();
    let mut manifest_value = value["manifest"].take();
    manifest_value["action"] = serde_json::to_value(action).unwrap();
    manifest_value["arguments_blake3"] = Value::String(arguments_identity_blake3(&request.arguments).unwrap());
    manifest_value["environment_blake3"] = Value::String(environment_identity_blake3(&request.admitted_environment).unwrap());
    let manifest = seal_wrapper_manifest(serde_json::from_value::<WrapperInvocationManifestInput>(manifest_value).unwrap()).unwrap();
    std::fs::write(request.manifest_path.as_ref().unwrap(), serde_json::to_vec_pretty(&manifest).unwrap()).unwrap();
    request.expected_manifest_ref = Some(manifest.manifest_ref);
    let sealed = seal_wrapper_request(request).unwrap();
    println!("{}", serde_json::to_string(&sealed).unwrap());
}

